## Complete Example: Bug-Fixing Agent

Here's a complete working example:

**Python:**
```python
import asyncio
from claude_agent_sdk import query, ClaudeAgentOptions, AssistantMessage, ResultMessage, TextBlock

async def main():
    print("🤖 Bug-Fixing Agent Starting...\n")

    options = ClaudeAgentOptions(
        # Tools the agent can use
        allowed_tools=["Read", "Edit", "Glob", "Bash", "Grep"],
        # Auto-approve file edits
        permission_mode="acceptEdits",
        # Custom system instruction
        system_prompt="You are an expert Python developer. Always check for edge cases like division by zero.",
        # Max 10 conversation turns
        max_turns=10
    )

    async for message in query(
        prompt="""Analyze the file bugs.py for issues that would cause crashes.
        Identify each bug, explain why it's a problem, and fix it.""",
        options=options
    ):
        # Print Claude's reasoning
        if isinstance(message, AssistantMessage):
            for block in message.content:
                if isinstance(block, TextBlock):
                    print(f"🤔 Claude: {block.text}\n")

        # Print final result
        elif isinstance(message, ResultMessage):
            if message.subtype == 'success':
                print(f"\n✅ Task completed!")
                print(f"   Duration: {message.duration_ms}ms")
                print(f"   Cost: ${message.total_cost_usd}")
                print(f"   Turns: {message.num_turns}")
            else:
                print(f"\n❌ Task failed: {message.subtype}")

asyncio.run(main())
```

**TypeScript:**
```typescript
import { query } from "@anthropic-ai/claude-agent-sdk";

async function main() {
  console.log("🤖 Bug-Fixing Agent Starting...\n");

  for await (const message of query({
    prompt: `Analyze the file bugs.py for issues that would cause crashes.
    Identify each bug, explain why it's a problem, and fix it.`,
    options: {
      allowedTools: ["Read", "Edit", "Glob", "Bash", "Grep"],
      permissionMode: "acceptEdits",
      systemPrompt: "You are an expert Python developer. Always check for edge cases.",
      maxTurns: 10
    }
  })) {
    // Print Claude's reasoning
    if (message.type === "assistant" && message.message?.content) {
      for (const block of message.message.content) {
        if ("text" in block) {
          console.log(`🤔 Claude: ${block.text}\n`);
        }
      }
    }

    // Print final result
    if (message.type === "result") {
      if (message.subtype === "success") {
        console.log(`\n✅ Task completed!`);
        console.log(`   Duration: ${message.duration_ms}ms`);
        console.log(`   Cost: $${message.total_cost_usd}`);
      }
    }
  }
}

main().catch(console.error);
```

